import { EventEmitter, errorMonitor } from "node:events";
function main(): void {
  const e = new EventEmitter();
  e.on(errorMonitor, () => console.log("monitor"));
  e.on("error", () => console.log("handler"));
  e.emit("error", new Error("x"));
  const c = new EventEmitter({ captureRejections: true });
  c.on("x", async () => { throw new Error("async boom"); });
  c.on("error", (er: Error) => console.log("captured", er.message));
  c.emit("x");
}
